"""The generated-view header: what a view's first line says and the stamps it carries."""

from __future__ import annotations

import re
from dataclasses import dataclass

from ...core.digest import content_digest
from ...infra.fsio import FORMAT_LEVEL, NewerContent, parse_level

#: What every view's first line starts with, stamped or not.
GENERATED_PREFIX = (
    "<!-- GENERATED by `ddflow render`. Do not edit: the event log is the source of truth."
)
#: The first line a renderer emits; `render_views` stamps it (`stamp_view`).
GENERATED = GENERATED_PREFIX + " -->"

_VIEW_HEAD = re.compile(
    re.escape(GENERATED_PREFIX)
    + r"(?: body-sha256=(?P<sha>[0-9a-f]{12}))?(?P<extra>(?: [A-Za-z0-9_-]+=\S+)*) -->"
)


class NewerView(NewerContent):
    """A write would replace a view written at a higher format level (D-compat 2). The
    view carries no version, so the message names the level."""

    def __init__(self, what: str, fmt: int) -> None:
        RuntimeError.__init__(
            self,
            f"{what} was written at format level {fmt}, newer than this ddflow's "
            f"({FORMAT_LEVEL}); upgrade ddflow before regenerating it",
        )
        self.needs = ""
        self.fmt = fmt


@dataclass(frozen=True, slots=True)
class ViewHead:
    """What a written view's first line says (D-compat-json-views): the digest of the body
    that followed it and the FORMAT LEVEL. No ddflow version: a version stamp would rewrite
    every committed view on each release, and the pre-commit check would then disagree
    between clones on different versions."""

    sha: str | None
    fmt: int = 1


def split_view(text: str) -> tuple[ViewHead | None, str]:
    """``(head, body)`` of a view; ``(None, text)`` when its first line is not ours. A head
    without a digest is a view written before stamps existed."""
    first, _nl, rest = text.partition("\n")
    m = _VIEW_HEAD.fullmatch(first.removesuffix("\r"))
    if m is None:
        return None, text
    fmt = 1
    for pair in m.group("extra").split():
        k, _, v = pair.partition("=")
        level = parse_level(v) if k == "fmt" else None
        if level is not None:
            fmt = level
    return ViewHead(m.group("sha"), fmt), rest


def stamp_view(text: str, fmt: int | None = None) -> str:
    """``text`` (a view starting with ``GENERATED``) with its first line carrying the body's
    digest, and the format level when above 1 (as exports do: level 1 adds nothing)."""
    level = FORMAT_LEVEL if fmt is None else fmt
    _first, _nl, body = text.partition("\n")
    tail = f" fmt={level}" if level != 1 else ""
    digest = content_digest(body, length=12)
    return f"{GENERATED_PREFIX} body-sha256={digest}{tail} -->\n{body}"


def view_difference(have: str, want: str) -> str:
    """How a written view differs from the text a fresh render gives: "" when the body is
    the same (the first line, a stamp or none, is not compared), else ``newer`` (written at a
    higher format level: this version cannot regenerate it), ``edited`` (the body no longer
    matches its digest: a person changed it) or ``stale`` (the log moved since)."""
    head, body = split_view(have)
    _wh, want_body = split_view(want)
    if body == want_body:
        return ""
    if head is not None and head.fmt > FORMAT_LEVEL:
        return "newer"
    if head is not None and head.sha is not None and content_digest(body, length=12) != head.sha:
        return "edited"
    return "stale"
